export function untrustedMarkdownInline(value, maxLength = 256) {
    const text = typeof value === 'string' ? value : String(value ?? '');
    const oneLine = text
        .replace(/[\u0000-\u001f\u007f]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    const clipped = oneLine.length > maxLength ? `${oneLine.slice(0, maxLength - 1)}…` : oneLine;
    return clipped.replace(/[\\`*_{}\[\]<>#!|]/g, character => `\\${character}`);
}
